let state;try{state=JSON.parse(sessionStorage.getItem('cdtrack-prototype-v1'))||seed()}catch{state=seed()}
let draft=[{type:1}], role='requestor',view='dashboard',currentId=4823;
const drawerLabels=['Research Paper · faculty group A','Research Paper · faculty group B','Participants / permission','For Book','Appointment Letter','Certification / approval','Other Documents to Claim','College Organization Letter','Parental / Guardian Consent','Room Utilization / Faculty Loading','Other Forms','Change of Matriculation','Routing Form','Research Validation Sheet','Assignment of Research Personnel','Book Slips'];
const save=()=>sessionStorage.setItem('cdtrack-prototype-v1',JSON.stringify(state));
const req=id=>state.requests.find(r=>r.id===Number(id));
const typeName=id=>state.types.find(t=>t.id===Number(id))?.name||'Document';
const facultyName=id=>state.faculty.find(f=>f.id===Number(id))?.name||'Faculty';
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const reference=r=>'CDT-2026-'+r.id;
const status=r=>{const ss=r.docs.map(d=>d.status);if(ss.every(s=>s==='Claimed'))return 'Completed';if(ss.includes('Claimed'))return 'Partially claimed';if(ss.every(s=>s==='Ready for claim'))return 'Ready for claim';if(ss.includes('Ready for claim'))return 'Partially ready';if(ss.includes('Processing'))return 'Processing';if(ss.includes('Received'))return 'Received';return 'Awaiting drop-off'};
const badge=s=>'<span class="badge '+(s.includes('drop')?'awaiting':s==='Received'?'received':s.includes('ready')||s.includes('Ready')?'ready':s==='Completed'||s.includes('claimed')||s==='Claimed'?'claimed':'processing')+'">'+esc(s)+'</span>';
const mine=()=>role==='requestor'?state.requests.filter(r=>r.owner==='John Doe'||r.owner===state.profile.name):state.requests;
const now=()=>new Date().toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
function log(r,text){r.events.unshift({text,time:now(),by:'Mark Reyes'});state.audit.unshift({time:now(),name:'Mark Reyes',role:'STA',action:text,request:r.id});save()}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),5000)}
const link=(v,id)=>'#'+role+'/'+v+(id?'/'+id:'');
const button=(text,v,id,primary=false)=>'<a class="btn '+(primary?'btn-primary':'btn-outline-secondary')+'" href="'+link(v,id)+'">'+text+'</a>';
