const app=$('#app');
function render(){
 const bits=location.hash.replace('#','').split('/');role=['requestor','sta','admin'].includes(bits[0])?bits[0]:'requestor';view=bits[1]||'dashboard';currentId=Number(bits[2])||4823;
 if(!location.hash||bits[0]==='login'){login();return}
 const navs=role==='requestor'?[['dashboard','grid','Overview'],['new','plus','New request'],['requests','file','My requests'],['profile','user','Profile'],['help','help','Help']]:role==='sta'?[['dashboard','grid','Counter overview'],['requests','file','Request queue'],['storage','box','Drawer directory'],['history','history','Collection history'],['help','help','Help']]:[['dashboard','chart','Overview'],['history','history','Activity log'],['faculty','users','Faculty'],['types','file','Document types'],['users','user','User accounts'],['feedback','chat','Feedback']];
 const label={requestor:'Requestor portal',sta:'Counter staff portal',admin:'Admin / Supervisor portal'}[role];
 let content='';
 switch(view){case'dashboard':content=role==='admin'?adminDashboard():dashboard();break;case'requests':content=requestList();break;case'new':content=newRequest();break;case'detail':content=detail();break;case'confirmation':content=confirmation();break;case'stub':content=stub();break;case'feedback':content=role==='admin'?feedbackRecords():feedbackForm();break;case'profile':content=profile();break;case'storage':content=storage();break;case'history':content=history();break;case'faculty':case'types':case'users':content=directory(view);break;case'release':content=releaseForm();break;default:content=help()}
 app.innerHTML=demoBar()+'<div class="shell"><aside class="sidebar" aria-label="Portal navigation"><div class="brand"><img src="cae-emblem.jpg" alt="College of Accounting Education emblem"><div><strong>CDTrack</strong><span>CAE DEAN’S OFFICE</span></div></div><p class="portal-name">'+label+'</p><nav class="nav">'+navs.map(([v,i,n])=>'<a href="'+link(v)+'" class="'+(view===v?'active':'')+'" '+(view===v?'aria-current="page"':'')+'>'+icon(i)+n+'</a>').join('')+'</nav><div class="sidebar-footer"><a href="#login">'+icon('logout')+'Return to login</a><p>University of Mindanao<br>College of Accounting Education</p><a href="../docs/SPECIFICATION.md" target="_blank">Prototype specification</a></div></aside><div class="workarea"><header class="topbar"><button class="btn quiet mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false">'+icon('menu')+'</button><span class="breadcrumb">Dean’s Office <span aria-hidden="true"> / </span> '+label+'</span><div class="account"><span class="avatar" aria-hidden="true">'+({requestor:'JD',sta:'MR',admin:'GR'}[role])+'</span><label class="small" for="role-switch">Preview as</label><select id="role-switch" aria-label="Switch demo portal"><option value="requestor" '+(role==='requestor'?'selected':'')+'>Requestor</option><option value="sta" '+(role==='sta'?'selected':'')+'>Counter staff</option><option value="admin" '+(role==='admin'?'selected':'')+'>Admin</option></select></div></header><main id="main" class="main">'+content+'</main></div></div>';
 bind();
}
function demoBar(){return '<div class="prototype-bar"><span>Interactive prototype · sample data <span class="optional">· changes stay in this browser tab</span></span><button data-action="reset">Reset demo</button></div>'}
function login(){
 app.innerHTML=demoBar()+'<main id="main" class="login-layout"><section class="login-story"><div class="brand"><img src="cae-emblem.jpg" alt="College of Accounting Education emblem"><div><strong>CDTrack</strong><span>CAE DEAN’S OFFICE</span></div></div><div class="intro"><h2>Your documents. <br>A clear path <br>from drop-off <br>to collection.</h2><p>Submit your request, follow its progress, and know when to visit the counter.</p><div class="login-journey"><div>'+icon('file')+'Submit a request and get your claim reference</div><div>'+icon('box')+'Bring your physical documents to the counter</div><div>'+icon('check')+'Collect them when they’re ready</div></div></div><div class="login-footer">University of Mindanao · College of Accounting Education</div></section><section class="login-form-wrap"><h1>Welcome to CDTrack</h1><p>Access your requests and office workspace.</p><button class="btn full" data-action="google">'+icon('shield')+'Continue with Google</button><div class="or">or use your email</div><form id="login-form" class="stack">'+fields('login-email','Email address','','email',true)+'<div class="field"><label for="login-password">Password</label><div class="actions"><input style="flex:1;min-width:0" id="login-password" type="password" autocomplete="off" required placeholder="Use any demo password"><button type="button" class="btn btn-outline-secondary" data-action="password" aria-label="Show password">'+icon('eye')+'</button></div><small>Demo only. Do not enter your real password.</small></div><div class="spread"><label class="small"><input type="checkbox" disabled> Remember me <span class="muted">(live system)</span></label><button type="button" class="text-btn small" data-action="recovery">Forgot password?</button></div><button class="btn btn-primary full">Open requestor demo '+icon('arrow')+'</button><p id="login-note" class="inline-note" role="status"></p></form><div class="or">explore the sample workspaces</div><div class="demo-roles"><a class="btn btn-outline-secondary" href="#requestor/dashboard">Requestor</a><a class="btn btn-outline-secondary" href="#sta/dashboard">Counter staff</a><a class="btn btn-outline-secondary" href="#admin/dashboard">Admin</a></div><p class="login-help">Account registration and recovery screens are illustrative.<br><button class="text-btn small" data-action="registration">How will I get an account?</button></p></section></main>';
 bind();
}
function stats(rs){
 const metrics=[
  {label:'Total batches',value:rs.length,detail:'All submitted requests',icon:'file',tone:'total'},
  {label:'Active requests',value:rs.filter(r=>status(r)!=='Completed').length,detail:'Not fully collected',icon:'clock',tone:'active'},
  {label:'Ready for collection',value:rs.filter(r=>r.docs.some(d=>d.status==='Ready for claim')).length,detail:'Batches with ready documents',icon:'box',tone:'ready'},
  {label:'Completed',value:rs.filter(r=>status(r)==='Completed').length,detail:'All documents collected',icon:'check',tone:'completed'}
 ];
 return '<div class="row row-cols-1 row-cols-sm-2 row-cols-xl-4 g-3 dashboard-metrics" aria-label="Request summary">'+metrics.map(m=>'<div class="col"><section class="card h-100 metric-card metric-'+m.tone+'"><div class="card-body"><div class="metric-top"><h2 class="card-title">'+m.label+'</h2><span class="metric-icon" aria-hidden="true">'+icon(m.icon)+'</span></div><p class="metric-value">'+m.value+'</p><p class="card-text">'+m.detail+'</p></div></section></div>').join('')+'</div>';
}
function requestTable(rs,staff=false){
return '<div class="table-responsive table-wrap"><table class="table table-hover align-middle request-table"><thead><tr><th>Request</th>'+(staff?'<th>Requestor</th>':'')+'<th>Documents</th><th>Status</th><th>'+(staff?'Needed by':'Submitted')+'</th><th><span class="muted">Action</span></th></tr></thead><tbody>'+rs.map(r=>'<tr data-search="'+esc([reference(r),r.owner,...r.docs.map(d=>typeName(d.type))].join(' ').toLowerCase())+'" data-status="'+esc(status(r))+'"><td class="cell-ref"><strong class="mono">#'+r.id+'</strong><span class="secondary">'+r.docs.length+' document'+(r.docs.length>1?'s':'')+'</span></td>'+(staff?'<td class="cell-owner">'+esc(r.owner)+'</td>':'')+'<td class="cell-documents">'+esc(typeName(r.docs[0].type))+(r.docs.length>1?'<span class="secondary">+ '+(r.docs.length-1)+' more document</span>':'')+'</td><td class="cell-status">'+badge(status(r))+'</td><td class="cell-date mono small">'+date(staff?r.needed:r.created)+'</td><td class="cell-action"><a class="text-btn" href="'+link('detail',r.id)+'">'+(staff?'Manage':'View')+'</a></td></tr>').join('')+'</tbody></table></div>'+(rs.length?'':'<div class="empty"><h3>No requests yet</h3><p>Submit a request to start tracking your documents.</p>'+button('New request','new',null,true)+'</div>')+'<div id="filter-empty" class="empty" hidden><h3>No matching requests</h3><p>Try a different reference, name, or status.</p></div>';
}
function dashboard(){
 const rs=mine(),staff=role==='sta';
 const active=rs.filter(r=>status(r)!=='Completed');
 const readyBatch=rs.find(r=>r.docs.some(d=>d.status==='Ready for claim'));
 const waitingBatch=rs.find(r=>r.docs.some(d=>d.status==='Awaiting drop-off'));
 const updates=rs.flatMap(r=>r.events.map(e=>({r,e}))).sort((a,b)=>Date.parse(b.e.time.replace(',', ' 2026'))-Date.parse(a.e.time.replace(',', ' 2026'))).slice(0,3);
 return head(staff?'Counter overview':'Good morning, '+esc(state.profile.name.split(' ')[0])+'.',staff?'Receive, route, and release documents from one working queue.':'Here’s where your documents are—and what to do next.',button(icon('plus')+(staff?'Record a request':'New request'),'new',null,true))+stats(rs)+
 '<div class="alert alert-success notice">'+icon(staff?'file':'check')+'<div><h2>'+(staff?rs.filter(r=>r.docs.some(d=>d.status==='Awaiting drop-off')).length+' batch awaiting physical drop-off':readyBatch?'You have documents ready to collect':waitingBatch?'Your next step: bring the hardcopies':'Your requests are up to date')+'</h2><p>'+(staff?'Open the batch and confirm each document actually received.':readyBatch?'Check the ready items before visiting. Other documents may still be processing.':waitingBatch?'Bring your reference and physical documents so counter staff can record receipt.':'Open a request to review its progress or collection history.')+'</p></div>'+button(staff?'Open queue':readyBatch?'View ready documents':waitingBatch?'View pending drop-off':'View requests',staff||(!readyBatch&&!waitingBatch)?'requests':'detail',staff?null:(readyBatch||waitingBatch)?.id)+'</div>'+
 '<div class="two-col"><section class="card"><div class="card-header"><h2>'+(staff?'Working queue':'Your active requests')+'</h2><a class="text-btn small" href="'+link('requests')+'">View all</a></div>'+requestTable(active,staff)+'<div class="table-bottom">'+active.length+' active batches · individual document status inside each request</div></section><aside class="stack"><section class="card"><div class="card-header"><h2>'+(staff?'Recent counter activity':'Latest updates')+'</h2></div><div class="card-body"><ul class="activity">'+updates.map(({r,e})=>'<li>'+icon(r.docs.some(d=>d.status==='Ready for claim')?'check':'clock')+'<div><strong>#'+r.id+'</strong><br>'+esc(e.text)+'<small>'+esc(e.time)+'</small></div></li>').join('')+'</ul></div></section><section><h3>'+(staff?'One batch. Individual documents.':'Before you visit')+'</h3><p class="legend">'+(staff?'A batch is complete only when every document has been collected. Record partial collection without closing the remaining items.':'Bring your claim reference and identification. A submitted request does not mean your physical documents have been received.')+'</p></section></aside></div>';
}
function requestList(){
 const rs=mine();return head(role==='sta'?'Request queue':'My requests','Search a batch, then open it to see each document’s progress.',button(icon('plus')+'New request','new',null,true))+
 '<div class="toolbar"><label class="search">'+icon('search')+'<input id="search" aria-label="Search requests" placeholder="Search reference, document'+(role==='sta'?', or name':'')+'"></label><select id="status-filter" aria-label="Filter by status"><option value="">All statuses</option>'+['Awaiting drop-off','Received','Processing','Partially ready','Ready for claim','Partially claimed','Completed'].map(s=>'<option>'+s+'</option>').join('')+'</select></div><section class="card">'+requestTable(rs,role==='sta')+'<div class="table-bottom">Showing sample requests · batch status reflects its individual documents</div></section>';
}
function documentRow(i){
 return '<section class="document-form" data-doc-row><div class="spread"><h3>Document '+(i+1)+'</h3><button type="button" class="text-btn small" data-action="remove-doc" data-index="'+i+'" '+(draft.length===1?'disabled':'')+'>Remove</button></div><div class="field"><label for="type-'+i+'">Document type</label><select id="type-'+i+'" name="type-'+i+'">'+state.types.filter(t=>t.active).map(t=>'<option value="'+t.id+'">'+esc(t.name)+'</option>').join('')+'</select></div><fieldset style="margin-top:15px"><legend class="small">Faculty for this document</legend><div class="faculty-checks">'+state.faculty.filter(f=>f.active).map(f=>'<label><input type="checkbox" name="faculty-'+i+'" value="'+f.id+'">'+esc(f.name)+'</label>').join('')+'</div><p class="inline-note">Select the people who need to handle this document. Routing order is not implied.</p></fieldset></section>';
}
function newRequest(){
 return head('New document request','Group related documents under one reference. Choose faculty separately for each document.')+'<form id="request-form"><div class="two-col"><div class="stack"><section class="card"><div class="card-header"><h2>Documents & faculty</h2></div><div class="card-body"><div id="document-rows">'+draft.map((_,i)=>documentRow(i)).join('')+'</div><button class="btn btn-outline-secondary" type="button" data-action="add-doc">'+icon('plus')+'Add another document</button></div></section><section class="card"><div class="card-header"><h2>Request details</h2></div><div class="card-body form-grid">'+(role==='sta'?fields('requestor-name','Requestor name','','text',true):'')+fields('needed','Date needed','','date',true)+'<div class="field '+(role==='sta'?'wide':'')+'"><label for="purpose">Purpose</label><input id="purpose" name="purpose" required maxlength="160" placeholder="What do you need the documents for?"></div><div class="field wide"><label for="notes">Additional notes <span class="muted">(optional)</span></label><textarea id="notes" name="notes" maxlength="500"></textarea></div></div></section><section class="card"><div class="card-header"><h2>Supporting files <span class="muted small">(optional)</span></h2></div><div class="card-body"><div class="upload"><label for="files" class="small">Choose reference scans</label><p><input id="files" type="file" multiple accept=".pdf,.png,.jpg,.jpeg"></p><p>PDF, PNG, or JPG · up to 10 MB per file in this prototype.</p></div><p class="inline-note">Files are selected locally for preview. Their contents are not uploaded or saved.</p></div></section></div><aside class="stack"><section class="card"><div class="card-header"><h2>What happens next</h2></div><div class="card-body"><ul class="activity"><li>'+icon('file')+'<div><strong>Get your reference</strong><br>One reference for this batch.</div></li><li>'+icon('box')+'<div><strong>Drop off the hardcopies</strong><br>Staff confirm receipt of each document.</div></li><li>'+icon('check')+'<div><strong>Track and collect</strong><br>See which documents are ready.</div></li></ul><div class="summary-total"><p class="legend">Your needed date is a request, not a confirmed completion date.</p><p id="form-error" class="error" role="alert"></p><button class="btn btn-primary full">Submit request '+icon('arrow')+'</button><a class="btn quiet full" href="'+link('requests')+'">Cancel</a></div></div></section></aside></div></form>';
}
function detail(){
 const r=req(currentId);if(!r)return head('Request not found','Return to your request list.')+button('View requests','requests');
 const staff=role==='sta';const ready=r.docs.filter(d=>d.status==='Ready for claim');const complete=status(r)==='Completed';
 const phases=['Submitted','Received','Processing','Ready','Claimed'];let stage=0;if(r.docs.every(d=>d.status!=='Awaiting drop-off'))stage=1;if(r.docs.every(d=>['Processing','Ready for claim','Claimed'].includes(d.status)))stage=2;if(r.docs.every(d=>['Ready for claim','Claimed'].includes(d.status)))stage=3;if(complete)stage=4;
 return '<a class="back" href="'+link('requests')+'">'+icon('back')+'All requests</a>'+head('Request #'+r.id,reference(r)+' · submitted '+date(r.created),'<div class="actions">'+button(icon('download')+'Claim stub','stub',r.id)+(staff&&ready.length?button('Record collection','release',r.id,true):'')+'</div>')+
 '<div class="spread" style="margin-bottom:8px">'+badge(status(r))+'<span class="small muted">'+r.docs.filter(d=>d.status==='Claimed').length+' of '+r.docs.length+' documents collected</span></div>'+
 '<ol class="steps" aria-label="Batch progress">'+phases.map((p,i)=>'<li class="'+(i<=stage?'done':'')+'">'+p+'</li>').join('')+'</ol>'+
 '<div class="two-col"><div class="stack"><section class="card"><div class="card-header"><h2>Documents in this batch</h2><span class="small muted">'+r.docs.length+' items</span></div>'+r.docs.map(d=>'<article class="document-detail"><div class="spread"><div><h3>'+esc(typeName(d.type))+'</h3><p>Faculty: '+d.faculty.map(facultyName).map(esc).join(', ')+'</p><p>'+(d.drawer?'Current location: drawer '+d.drawer:d.status==='Claimed'?'Collected · previous drawer '+(d.previousDrawer||'not recorded'):d.status==='Awaiting drop-off'?'Physical document not yet received':d.status==='Processing'?'With faculty / in processing':'Received at the counter')+'</p></div>'+badge(d.status)+'</div>'+(staff?documentActions(r,d):'')+'</article>').join('')+'</section>'+
 '<section class="card"><div class="card-header"><h2>Tracking history</h2></div><div class="card-body"><ul class="activity">'+r.events.map(e=>'<li>'+icon('history')+'<div>'+esc(e.text)+'<small>'+esc(e.time)+' · '+esc(e.by)+'</small></div></li>').join('')+'</ul></div></section></div><aside class="stack"><section class="card"><div class="card-header"><h2>Request information</h2></div><div class="card-body"><dl class="info-list"><div><dt>Requestor</dt><dd>'+esc(r.owner)+'</dd></div><div><dt>Date needed</dt><dd>'+date(r.needed)+'</dd></div><div><dt>Purpose</dt><dd>'+esc(r.purpose)+'</dd></div><div><dt>Notes</dt><dd>'+esc(r.notes||'No additional notes')+'</dd></div>'+(r.files?.length?'<div><dt>Reference files · names only</dt><dd>'+r.files.map(esc).join('<br>')+'</dd></div>':'')+'</dl></div></section>'+
 (complete&&role==='requestor'?'<section><h3>How was your experience?</h3><p class="legend">Rate counter service and processing separately.</p>'+button(state.feedback.some(f=>f.request===r.id)?'View your feedback':'Leave feedback','feedback',r.id)+'</section>':'<section><h3>'+(ready.length?'Ready items can be collected':'Keep your claim reference')+'</h3><p class="legend">'+(ready.length?'Only ready documents can be released. Other documents stay active until their processing is finished.':'The counter uses your reference to locate the batch. Check this page before visiting.')+'</p></section>')+'</aside></div>';
}
function documentActions(r,d){
 let html='';
 if(d.status==='Awaiting drop-off')html='<button class="btn btn-sm btn-primary" data-action="receive" data-id="'+r.id+'" data-doc="'+d.id+'">'+icon('check')+'Confirm physical receipt</button>';
 if(d.status==='Received')html='<button class="btn btn-sm btn-primary" data-action="route" data-id="'+r.id+'" data-doc="'+d.id+'">'+icon('arrow')+'Route to faculty</button>';
 if(d.status==='Processing')html='<label class="small" for="drawer-'+d.id+'">Returned document drawer</label><select id="drawer-'+d.id+'" aria-label="Drawer for '+esc(typeName(d.type))+'"><option value="">Choose drawer</option>'+drawerLabels.map((n,i)=>'<option value="'+(i+1)+'">'+(i+1)+' · '+esc(n)+'</option>').join('')+'</select><button class="btn btn-sm btn-primary" data-action="ready" data-id="'+r.id+'" data-doc="'+d.id+'">Confirm return & mark ready</button>';
 if(d.status==='Ready for claim')html='<span class="small muted">Include this document when recording collection.</span>';
 if(d.status==='Claimed')html='<span class="small muted">Release recorded. Current storage cleared.</span>';
 return '<div class="actions">'+html+'</div>';
}
function confirmation(){const r=req(currentId);if(!r)return detail();return head('Request submitted','Your batch has been created. The next step is physical drop-off.')+'<section class="card" style="max-width:700px;margin:auto"><div class="success-state">'+icon('check')+'<h2>Keep this claim reference</h2><div class="reference">'+reference(r)+'</div><p class="muted">'+r.docs.length+' document'+(r.docs.length>1?'s':'')+' · '+esc(r.owner)+'</p><p>Bring the physical documents to the CAE Dean’s Office counter.<br>Staff will confirm receipt of each item.</p><div class="actions" style="justify-content:center">'+button('Track this request','detail',r.id,true)+button('View / print stub','stub',r.id)+'</div></div></section>'}
function stub(){const r=req(currentId);if(!r)return detail();return head('Claim stub','Print or save as PDF using your browser.', '<button class="btn btn-primary" data-action="print">'+icon('download')+'Print / save PDF</button>')+'<section class="stub"><div class="stub-header"><img src="cae-emblem.jpg" alt="CAE emblem"><div><h2>CAE Dean’s Office</h2><span class="small muted">CDTrack · Submission receipt</span></div></div><div class="reference">'+reference(r)+'</div><dl class="info-list"><div><dt>Requestor</dt><dd>'+esc(r.owner)+'</dd></div><div><dt>Submitted</dt><dd>'+date(r.created)+'</dd></div></dl><h3 style="margin-top:24px">Documents</h3><ol>'+r.docs.map(d=>'<li>'+esc(typeName(d.type))+'<br><span class="muted small">'+d.faculty.map(facultyName).map(esc).join(', ')+'</span></li>').join('')+'</ol><p class="legend">This receipt confirms digital submission, not physical receipt. Bring the reference when dropping off or collecting documents.</p><p class="legend">PROTOTYPE · SAMPLE DATA · NOT AN OFFICIAL RECEIPT</p></section>'}
function releaseForm(){const r=req(currentId);if(role!=='sta'||!r)return detail();const ready=r.docs.filter(d=>d.status==='Ready for claim');return '<a class="back" href="'+link('detail',r.id)+'">'+icon('back')+'Request #'+r.id+'</a>'+head('Record collection','Select only the documents physically handed to the claimant.')+'<form id="release-form" data-id="'+r.id+'" class="card" style="max-width:760px"><div class="card-body"><fieldset class="form-section"><legend>Ready documents</legend>'+ready.map(d=>'<label class="check-row"><input type="checkbox" name="release-doc" value="'+d.id+'" checked>'+esc(typeName(d.type))+' · drawer '+d.drawer+'</label>').join('')+(!ready.length?'<p>No documents are ready for collection.</p>':'')+'</fieldset><div class="form-section form-grid"><div class="field"><label for="claimant-type">Collected by</label><select id="claimant-type" name="claimant-type"><option value="self">Requestor</option><option value="representative">Authorized representative</option></select></div>'+fields('claimant','Claimant name',r.owner,'text',true)+fields('acknowledgment','Signed stub / acknowledgment reference','','text',true)+'<div class="field"><label for="authorization">Representative authorization reference</label><input id="authorization" name="authorization" placeholder="Required for a representative"></div><label class="check-row wide"><input type="checkbox" required>I checked the claimant’s identification and acknowledgment.</label></div><p class="legend">Released by Mark Reyes · time recorded on confirmation. Unselected documents remain in the request.</p><p id="release-error" class="error" role="alert"></p><div class="actions"><button class="btn btn-primary" '+(!ready.length?'disabled':'')+'>Confirm collection</button>'+button('Cancel','detail',r.id)+'</div></div></form>'}
function feedbackForm(){const r=req(currentId);if(!r)return detail();if(status(r)!=='Completed')return head('Feedback opens after collection','Complete collection of all documents in this batch first.')+button('View request','detail',r.id);const f=state.feedback.find(f=>f.request===r.id);if(f)return head('Thank you for your feedback','Request #'+r.id)+'<section class="card"><div class="card-body"><p>Counter service: <strong>'+f.service+'/5</strong></p><p>Processing speed: <strong>'+f.speed+'/5</strong></p><p>'+esc(f.comment||'No additional comments.')+'</p>'+button('Back to request','detail',r.id)+'</div></section>';
 const scale=(n,label)=>'<fieldset class="form-section"><legend>'+label+'</legend><div class="rating">'+[1,2,3,4,5].map(x=>'<label><input type="radio" name="'+n+'" value="'+x+'" required aria-label="'+x+' out of 5"><span>'+x+'</span></label>').join('')+'</div><div class="ratings-labels"><span>Very dissatisfied</span><span>Very satisfied</span></div></fieldset>';
 return head('How was your experience?','Optional feedback for completed request #'+r.id)+ '<form id="feedback-form" data-id="'+r.id+'" class="card" style="max-width:700px"><div class="card-body">'+scale('service','Counter staff service quality')+scale('speed','Workflow & processing speed')+'<div class="field form-section"><label for="comment">Comments or suggestions <span class="muted">(optional)</span></label><textarea id="comment" name="comment" maxlength="300"></textarea><small>Up to 300 characters.</small></div><div class="actions"><button class="btn btn-primary">Submit feedback</button>'+button('Cancel','detail',r.id)+'</div></div></form>';
}
function profile(){return head('Your profile','Keep your contact details current.')+'<form id="profile-form" class="card" style="max-width:780px"><div class="card-body form-grid">'+fields('name','Full name',state.profile.name,'text',true)+fields('email','Email address',state.profile.email,'email',true)+fields('department','Program / department',state.profile.department)+fields('phone','Contact number',state.profile.phone,'tel')+'<div class="wide"><p class="legend">Prototype changes stay in this tab. Email verification is not connected.</p><button class="btn btn-primary">Save changes</button></div></div></form>'}
function storage(){return head('Drawer directory','Find a physical filing location, then open a request to record its placement.')+'<div class="alert alert-success notice">'+icon('box')+'<div><h2>16 sample drawer assignments</h2><p>The paper mentions 20 drawers. These 16 labels follow the submitted counter prototype and still need office verification.</p></div></div><div class="toolbar"><label class="search">'+icon('search')+'<input id="search" placeholder="Search drawer number or document" aria-label="Search drawers"></label></div><section class="card"><div class="table-responsive table-wrap compact"><table class="table table-hover align-middle"><thead><tr><th>Drawer</th><th>Filing category</th><th>Stored documents</th><th>Request</th></tr></thead><tbody>'+drawerLabels.map((n,i)=>{const items=state.requests.flatMap(r=>r.docs.filter(d=>d.drawer===i+1).map(d=>({r,d})));return '<tr data-search="'+esc(((i+1)+' '+n).toLowerCase())+'"><td><span class="drawer-number">'+(i+1)+'</span></td><td>'+esc(n)+'</td><td>'+items.length+'</td><td>'+items.map(({r})=>'<a class="text-btn" href="'+link('detail',r.id)+'">#'+r.id+'</a>').join(' ')+'</td></tr>'}).join('')+'</tbody></table></div><div id="filter-empty" class="empty" hidden>No matching drawers. Try a different category.</div></section>'}
function history(){
 if(role==='admin')return head('Activity log','Administrative changes and document-handling events in one searchable record.')+'<div class="toolbar"><label class="search">'+icon('search')+'<input id="search" aria-label="Search activity" placeholder="Search user, action, or reference"></label></div><section class="card"><div class="table-responsive table-wrap"><table class="table table-hover align-middle"><thead><tr><th>When</th><th>Who</th><th>Role</th><th>Action</th><th>Request</th></tr></thead><tbody>'+state.audit.map(a=>'<tr data-search="'+esc([a.name,a.action,a.request].join(' ').toLowerCase())+'"><td class="small">'+esc(a.time)+'</td><td>'+esc(a.name)+'</td><td>'+a.role+'</td><td>'+esc(a.action)+'</td><td>'+(a.request?'<a href="'+link('detail',a.request)+'">#'+a.request+'</a>':'—')+'</td></tr>').join('')+'</tbody></table></div><div id="filter-empty" class="empty" hidden>No matching activity.</div></section>';
 const rs=state.requests.filter(r=>r.docs.some(d=>d.status==='Claimed'));return head('Collection history','Collected documents retain their former drawer and claimant details.')+'<section class="card"><div class="table-responsive table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Request</th><th>Document</th><th>Previous drawer</th><th>Claimant</th><th>Action</th></tr></thead><tbody>'+rs.flatMap(r=>r.docs.filter(d=>d.status==='Claimed').map(d=>'<tr><td>#'+r.id+'</td><td>'+esc(typeName(d.type))+'</td><td>'+(d.previousDrawer||'—')+'</td><td>'+esc(d.claimant||r.release?.claimant||r.owner)+'</td><td><a class="text-btn" href="'+link('detail',r.id)+'">View history</a></td></tr>')).join('')+'</tbody></table></div></section>';
}
function adminDashboard(){
 const rs=state.requests;const bars=arr=>arr.map(([label,n],i)=>'<div class="bar-row"><span>'+esc(label)+'</span><div class="bar-track"><div class="bar-fill '+(i%2?'gold':'')+'" style="width:'+Math.max(n/Math.max(...arr.map(a=>a[1]),1)*100,0)+'%"></div></div><strong>'+n+'</strong></div>').join('');
 return head('Office overview','A clear view of document demand, progress, and service feedback.','<span class="date-line">All sample records</span>')+stats(rs)+'<div class="equal-col"><section class="card"><div class="card-header"><h2>Batches by status</h2></div><div class="card-body">'+bars(['Awaiting drop-off','Received','Processing','Partially ready','Ready for claim','Partially claimed','Completed'].map(s=>[s,rs.filter(r=>status(r)===s).length]))+'<p class="legend">Each batch is counted once under its current overall status.</p></div></section><section class="card"><div class="card-header"><h2>Documents by type</h2></div><div class="card-body">'+bars(state.types.map(t=>[t.name,rs.flatMap(r=>r.docs).filter(d=>d.type===t.id).length]))+'<p class="legend">Counts individual documents. A batch can contain several types.</p></div></section></div><div class="equal-col" style="margin-top:24px"><section class="card"><div class="card-header"><h2>Service feedback</h2><a class="text-btn small" href="'+link('feedback')+'">View feedback</a></div><div class="card-body"><div class="feedback-summary"><div><strong>'+average('service')+'</strong><p class="small muted">Counter service / 5</p></div><div><strong>'+average('speed')+'</strong><p class="small muted">Processing speed / 5</p></div></div><p class="legend">'+state.feedback.length+' feedback submission'+(state.feedback.length===1?'':'s')+' · ratings shown separately</p></div></section><section class="card"><div class="card-header"><h2>Processing turnaround</h2></div><div class="card-body"><h3>Not calculated in this prototype</h3><p class="legend">The measurement needs a confirmed start and end: physical receipt to readiness, or submission to collection. No estimate is presented as an observed result.</p></div></section></div>';
}
function average(k){return state.feedback.length?(state.feedback.reduce((n,f)=>n+f[k],0)/state.feedback.length).toFixed(1):'—'}
function directory(kind){
 const labels={faculty:['Faculty','faculty member'],types:['Document types','document type'],users:['User accounts','user']};const [title,singular]=labels[kind];const data=state[kind];
 return head(title,kind==='users'?'Manage access while preserving past actions and transactions.':'Maintain the choices available when a request is created.','<button class="btn btn-primary" data-action="show-add">'+icon('plus')+'Add '+singular+'</button>')+
 '<section class="card"><form id="directory-form" class="inline-form" data-kind="'+kind+'" hidden><h2 id="directory-form-title">Add '+singular+'</h2><input type="hidden" name="edit-id"><div class="form-grid">'+fields('entry-name',kind==='users'?'Full name':'Name','','text',true)+(kind==='faculty'?fields('entry-department','Department','CAE'):kind==='users'?fields('entry-email','Email address','','email',true)+'<div class="field"><label for="entry-role">Role</label><select id="entry-role" name="entry-role"><option>Requestor</option><option>STA</option><option>Admin</option></select></div>':'')+'</div><div class="actions" style="margin-top:16px"><button class="btn btn-primary">Save</button><button class="btn btn-outline-secondary" type="button" data-action="hide-add">Cancel</button></div><p class="error" id="directory-error" role="alert"></p></form><div class="table-responsive table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Name</th>'+(kind==='faculty'?'<th>Department</th>':kind==='users'?'<th>Email</th><th>Role</th>':'<th>Documents</th>')+'<th>Status</th><th>Actions</th></tr></thead><tbody>'+data.map(x=>'<tr><td><strong>'+esc(x.name)+'</strong></td>'+(kind==='faculty'?'<td>'+esc(x.department)+'</td>':kind==='users'?'<td>'+esc(x.email)+'</td><td>'+esc(x.role)+'</td>':'<td>'+state.requests.flatMap(r=>r.docs).filter(d=>d.type===x.id).length+'</td>')+'<td><span class="badge '+(x.active?'ready':'claimed')+'">'+(x.active?'Active':'Inactive')+'</span></td><td><div class="actions" style="justify-content:flex-end"><button class="btn btn-sm" data-action="edit-entry" data-kind="'+kind+'" data-id="'+x.id+'">Edit</button><button class="btn btn-sm" data-action="toggle-entry" data-kind="'+kind+'" data-id="'+x.id+'">'+(x.active?'Disable':'Enable')+'</button></div></td></tr>').join('')+'</tbody></table></div><div class="table-bottom">Disabled records remain available in existing transaction history.</div></section>';
}
function feedbackRecords(){return head('Feedback records','Optional feedback from completed requests. Both rating criteria remain visible.')+'<section class="card"><div class="table-responsive table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Request</th><th>Requestor</th><th>Counter service</th><th>Processing</th><th>Comment</th><th>Date</th></tr></thead><tbody>'+state.feedback.map(f=>'<tr><td>#'+f.request+'</td><td>'+esc(f.name)+'</td><td>'+f.service+' / 5</td><td>'+f.speed+' / 5</td><td>'+esc(f.comment||'No comment')+'</td><td class="small">'+date(f.date)+'</td></tr>').join('')+'</tbody></table></div></section>'}
function help(){return head('How CDTrack works','A quick guide to the physical document process.')+'<section class="card"><div class="card-body">'+[['Submit online','Create one batch, add each document, and select the faculty who should handle it. Save the claim reference.'],['Bring the physical documents','Staff confirm receipt at the counter. Uploading reference scans does not replace physical drop-off.'],['Follow each document','A batch can have documents at different stages. The detail page shows routing, storage, and collection readiness.'],['Collect ready documents','Bring your reference and identification. Staff record the claimant, acknowledgment, and the exact documents handed over.'],['Prototype boundaries','This is a frontend demonstration. Authentication, database persistence, email delivery, file uploads, and office policy verification are not connected.']].map(([h,p])=>'<div class="help-block"><h2>'+h+'</h2><p>'+p+'</p></div>').join('')+'</div></section>'}
function filter(){let shown=0;$$('tr[data-search]').forEach(tr=>{const yes=tr.dataset.search.includes(($('#search')?.value||'').toLowerCase())&&(!$('#status-filter')?.value||tr.dataset.status===$('#status-filter').value);tr.hidden=!yes;if(yes)shown++});if($('#filter-empty'))$('#filter-empty').hidden=shown>0}
function bootstrapComponents(root=document){
 $$('input:not([type="checkbox"]):not([type="radio"]):not([type="hidden"]),textarea',root).forEach(el=>el.classList.add('form-control'));
 $$('select',root).forEach(el=>el.classList.add('form-select'));
 $$('input[type="checkbox"],input[type="radio"]',root).forEach(el=>{if(!el.closest('.rating'))el.classList.add('form-check-input')});
 $$('.field>label',root).forEach(el=>el.classList.add('form-label'));
 $$('.btn.small',root).forEach(el=>el.classList.add('btn-sm'));
 $$('.btn:not(.btn-primary):not(.quiet)',root).forEach(el=>el.classList.add('btn-outline-secondary'));
}
function bind(){
 bootstrapComponents();
 $('#role-switch')?.addEventListener('change',e=>{location.hash='#'+e.target.value+'/dashboard'});
 $('#search')?.addEventListener('input',filter);$('#status-filter')?.addEventListener('change',filter);
 $('#login-form')?.addEventListener('submit',e=>{e.preventDefault();location.hash='#requestor/dashboard'});
 $('#request-form')?.addEventListener('submit',submitRequest);
 $('#release-form')?.addEventListener('submit',submitRelease);
 $('#feedback-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),id=Number(e.target.dataset.id);if(state.feedback.some(x=>x.request===id))return;state.feedback.push({request:id,name:state.profile.name,service:Number(f.get('service')),speed:Number(f.get('speed')),comment:f.get('comment').trim(),date:new Date().toISOString().slice(0,10)});save();render();toast('Feedback saved in this demo.')});
 $('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),old=state.profile.name;state.profile=Object.fromEntries(f);state.requests.filter(r=>r.owner===old).forEach(r=>r.owner=state.profile.name);save();toast('Profile updated in this demo.')});
 $('#directory-form')?.addEventListener('submit',submitDirectory);
 $('#claimant-type')?.addEventListener('change',e=>{$('#authorization').required=e.target.value==='representative';if(e.target.value==='representative')$('#claimant').value='';else $('#claimant').value=req(currentId).owner});
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=Number(b.dataset.id),r=req(id),d=r?.docs.find(x=>x.id===Number(b.dataset.doc));
 if(a==='reset'){sessionStorage.removeItem('cdtrack-prototype-v1');state=seed();draft=[{}];render();toast('Sample data restored.')}
 if(a==='menu'){const open=$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',open)}
 if(a==='google')$('#login-note').textContent='Google sign-in is not connected in this prototype. Choose a sample workspace below.';
 if(a==='recovery')$('#login-note').textContent='In the live system, recovery will use a verified email address. No email is sent by this demo.';
 if(a==='registration')$('#login-note').textContent='The use case includes requester registration. Self-registration versus administrator approval is still an open product decision.';
 if(a==='password'){const p=$('#login-password');p.type=p.type==='password'?'text':'password';b.setAttribute('aria-label',p.type==='password'?'Show password':'Hide password')}
 if(a==='print')window.print();
 if(a==='add-doc'||a==='remove-doc'){
  const form=$('#request-form'),old=new FormData(form),files=$('#files');const snapshots=$$('[data-doc-row]').map((row,i)=>({type:old.get('type-'+i),faculty:old.getAll('faculty-'+i)}));
  if(a==='add-doc')snapshots.push({type:1,faculty:[]});else snapshots.splice(Number(b.dataset.index),1);
  draft=snapshots;$('#document-rows').innerHTML=draft.map((_,i)=>documentRow(i)).join('');
  snapshots.forEach((s,i)=>{$('#type-'+i).value=s.type;$$('input[name="faculty-'+i+'"]').forEach(x=>x.checked=s.faculty.includes(x.value))});
  bootstrapComponents($('#document-rows'));
  if(a==='add-doc')$('#type-'+(draft.length-1)).focus();
 }
 if(a==='receive'&&d?.status==='Awaiting drop-off'){d.status='Received';d.receivedAt=now();log(r,typeName(d.type)+' physically received at the counter.');render();toast('Physical receipt recorded.')}
 if(a==='route'&&d?.status==='Received'){d.status='Processing';log(r,typeName(d.type)+' routed to '+d.faculty.map(facultyName).join(', ')+'.');render();toast('Faculty routing recorded.')}
 if(a==='ready'&&d?.status==='Processing'){const v=$('#drawer-'+d.id).value;if(!v){toast('Choose the drawer holding this document first.');$('#drawer-'+d.id).focus();return}d.drawer=Number(v);d.status='Ready for claim';log(r,typeName(d.type)+' returned from faculty and filed in drawer '+v+'. Ready for claim.');render();toast('Document is ready for claim. No email was sent.')}
 if(a==='show-add'){$('#directory-form').hidden=false;$('#directory-form').reset();$('#directory-form-title').textContent='Add entry';$('#entry-name').focus()}
 if(a==='hide-add')$('#directory-form').hidden=true;
 if(a==='edit-entry'){const entry=state[b.dataset.kind].find(x=>x.id===id);const f=$('#directory-form');f.hidden=false;f.elements['edit-id'].value=id;$('#directory-form-title').textContent='Edit '+entry.name;$('#entry-name').value=entry.name;if($('#entry-department'))$('#entry-department').value=entry.department;if($('#entry-email'))$('#entry-email').value=entry.email;if($('#entry-role'))$('#entry-role').value=entry.role;$('#entry-name').focus()}
 if(a==='toggle-entry'){const entry=state[b.dataset.kind].find(x=>x.id===id);entry.active=!entry.active;state.audit.unshift({time:now(),name:'Grace Ramos',role:'Admin',action:(entry.active?'Enabled ':'Disabled ')+entry.name,request:null});save();render();toast('Availability updated. Historical records retained.')}
});
function submitRequest(e){
 e.preventDefault();const f=new FormData(e.target);const docs=draft.map((_,i)=>({id:i+1,type:Number(f.get('type-'+i)),faculty:f.getAll('faculty-'+i).map(Number),status:'Awaiting drop-off',drawer:null}));
 if(docs.some(d=>!d.faculty.length)){$('#form-error').textContent='Choose at least one faculty member for every document.';return}
 const files=[...$('#files').files];if(files.some(x=>x.size>10*1024*1024||!/.(pdf|png|jpe?g)$/i.test(x.name))){$('#form-error').textContent='Choose only PDF, PNG, or JPG files, each no larger than 10 MB.';return}
 const id=Math.max(...state.requests.map(r=>r.id))+1;
 const r={id,owner:role==='sta'?String(f.get('requestor-name')).trim():state.profile.name,created:new Date().toISOString().slice(0,10),needed:f.get('needed'),purpose:f.get('purpose').trim(),notes:f.get('notes').trim(),files:files.map(x=>x.name),docs,events:[{text:'Request submitted online. Physical receipt pending.',by:role==='sta'?'Mark Reyes':state.profile.name,time:now()}]};
 if(!r.purpose||!r.owner){$('#form-error').textContent='Enter the requestor and a meaningful purpose.';return}
 state.requests.unshift(r);state.audit.unshift({time:now(),name:role==='sta'?'Mark Reyes':state.profile.name,role:role==='sta'?'STA':'Requestor',action:'Created a request batch',request:id});save();draft=[{}];go('confirmation',id);
}
function submitRelease(e){
 e.preventDefault();const r=req(e.target.dataset.id),f=new FormData(e.target),ids=f.getAll('release-doc').map(Number);
 if(!ids.length){$('#release-error').textContent='Select at least one ready document to release.';return}
 if(!String(f.get('claimant')).trim()||!String(f.get('acknowledgment')).trim()){ $('#release-error').textContent='Enter the claimant and acknowledgment reference.';return}
 if(f.get('claimant-type')==='representative'&&!String(f.get('authorization')).trim()){ $('#release-error').textContent='Enter the representative authorization reference.';return}
 const docs=r.docs.filter(d=>ids.includes(d.id)&&d.status==='Ready for claim');docs.forEach(d=>{d.previousDrawer=d.drawer;d.drawer=null;d.status='Claimed';d.claimant=f.get('claimant').trim()});
 r.release={claimant:f.get('claimant').trim(),by:'Mark Reyes',time:now()};
 log(r,docs.map(d=>typeName(d.type)+' (drawer '+d.previousDrawer+')').join(', ')+' collected by '+r.release.claimant+(f.get('claimant-type')==='representative'?' as representative':'')+'. Acknowledgment: '+f.get('acknowledgment')+'.'+(f.get('authorization')?' Authorization: '+f.get('authorization')+'.':''));
 go('detail',r.id);toast('Collection recorded. Remaining documents stay active.');
}
function submitDirectory(e){
 e.preventDefault();const f=new FormData(e.target),kind=e.target.dataset.kind,edit=Number(f.get('edit-id')),name=String(f.get('entry-name')).trim();
 if(!name){$('#directory-error').textContent='Enter a name.';return}
 if(state[kind].some(x=>x.id!==edit&&(kind==='users'?x.email.toLowerCase()===String(f.get('entry-email')).trim().toLowerCase():x.name.toLowerCase()===name.toLowerCase()))){$('#directory-error').textContent='This '+(kind==='users'?'email address':'name')+' already exists.';return}
 let item=edit?state[kind].find(x=>x.id===edit):{id:Math.max(0,...state[kind].map(x=>x.id))+1,active:true};item.name=name;
 if(kind==='faculty')item.department=f.get('entry-department');
 if(kind==='users'){item.email=String(f.get('entry-email')).trim();item.role=f.get('entry-role')}
 if(!edit)state[kind].push(item);state.audit.unshift({time:now(),name:'Grace Ramos',role:'Admin',action:(edit?'Edited ':'Added ')+name,request:null});save();render();toast('Record saved in the demo.');
}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false')}});
